<script setup>
import { useConfirm } from 'primevue/useconfirm'
import { useRouter, useRoute } from 'vue-router'
import UploadFile from './UploadFile.vue'
import FileViewer from './FileViewer.vue'
import { getKnowledgeFileList, deleteKnowledgeFile, analysisKnowledgeFile } from '@/services/knowledge'
import useToastService from '@/hooks/useToastService'
import { i18nRender } from '@/locales'
import { nextTick } from 'vue'
import { fileIconRender, getFileType } from '../FileIcon'

const viewFileList = ref(['pdf', 'docx', 'txt', 'html', 'htm', 'md', 'json', 'jsonl', 'xml']) //, 'epub', 'mobi', 'pptx'

const toast = useToastService()
const confirm = useConfirm()
const router = useRouter()
const route = useRoute()
const fileList = ref([])
const total = ref(0)

const STATUS = {
  PARSING: 1,
  COMPLETED: 2,
  FAILED: -1,
  TOBEANA: 0
}

const kbId = route.query.id
const kbName = route.query.name

function removeFile(event, data) {
  confirm.require({
    target: event.currentTarget,
    message: i18nRender('kb.deleteConfirmMsg'),
    icon: 'pi pi-info-circle',
    rejectClass: 'p-button-secondary p-button-outlined p-button-sm',
    acceptClass: 'p-button-danger p-button-sm',
    rejectLabel: i18nRender('lang.cancel'),
    acceptLabel: i18nRender('kb.delete'),
    accept: () => {
      deleteKnowledgeFile(data.id).then(() => {
        toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.deleteSuccess'), life: 3000 })
        refreshData()
      })
    }
  })
}

const visible = ref(false)
const dialogTitle = ref('')
const uploadFileFlag = ref(false)
const fileViewerFlag = ref(false)

let getDownloadListTimer = null
function close() {
  visible.value = false
  resetDialog()
}
function resetDialog() {
  fileType.value = ''
  uploadFileFlag.value = false
  fileViewerFlag.value = false
}

function uploaded() {
  close()
  refreshData()
}
function importFile() {
  visible.value = true
  dialogTitle.value = i18nRender('kb.importFile')
  nextTick(() => {
    uploadFileFlag.value = true
  })
}

const fileName = ref('')
const fileType = ref('')
const fileId = ref('')
function openFile(data) {
  fileId.value = data.id
  fileName.value = data.name
  fileType.value = getFileType(fileName.value)

  visible.value = true
  dialogTitle.value = data.name
  nextTick(() => {
    fileViewerFlag.value = true
  })
}

let pager = {
  page: 1,
  pageSize: 10
}
function getTableData() {
  if (kbId) {
    getKnowledgeFileList({
      id: kbId,
      page: pager.page,
      pagesize: pager.pageSize
    }).then((res) => {
      const result = res.resData
      fileList.value = result.data
      total.value = result.total

      getDownloadListTimer = setTimeout(() => {
        getTableData()
      }, 500)
    })
  }
}

const firstPage = ref(0)
function refreshData() {
  pager.page = 1
  firstPage.value = 0
  getTableData()
}

function handlePageEvent(pageState) {
  pager.page = pageState.page + 1
  pager.pageSize = pageState.rows
  getTableData()
}
function iconRender(fileName) {
  const type = getFileType(fileName)
  return fileIconRender(type)
}

function analysisFile(id) {
  analysisKnowledgeFile({ id }).then((res) => {
    if (res.resCode === 0) {
      toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.analysisSuccess'), life: 3000 })
      getTableData()
    }
  })
}

onMounted(() => {
  getTableData()
})
</script>
<template>
  <div class="w-full m-5 h-full overflow-y-auto flex flex-col items-start justify-start overflow-x-hidden">
    <div class="flex justify-between items-center my-5 w-full">
      <Button text icon="pi pi-angle-left" :label="$t('kb.returnKb')" @click="router.replace('/knowledge')"></Button>
      <span class="font-bold text-xl">{{ kbName }}</span>
      <Button icon="pi pi-upload" :label="$t('kb.importFile')" @click="importFile"></Button>
    </div>
    <DataTable
      lazy
      :value="fileList"
      :paginator="total > 0"
      v-model:first="firstPage"
      :rows="10"
      :rowsPerPageOptions="[10, 20, 30]"
      :totalRecords="total"
      stripedRows
      rowHover
      resizableColumns
      dataKey="id"
      tableStyle="min-width: 50rem"
      @page="handlePageEvent"
      :pt="{ root: { style: { width: '100%' } } }"
    >
      <template #paginatorstart></template>
      <template #paginatorend> {{ $t('kb.total') }} {{ total }} {{ $t('kb.items') }}</template>

      <Column field="name" :header="$t('kb.name')">
        <template #body="{ data }">
          <div class="flex items-center">
            <img :src="iconRender(data.name)" alt="" style="width: 25px; margin-right: 5px" />
            <div class="file-title" v-tooltip="data.name">{{ data.name }}</div>
          </div>
        </template>
      </Column>
      <Column field="size" :header="$t('kb.fileSize')"></Column>
      <Column field="createtime" :header="$t('kb.uploadTime')"></Column>
      <Column field="operation" :header="$t('kb.operation')">
        <template #body="slotProps">
          <Button
            :label="$t('kb.analysis')"
            :disabled="[STATUS.PARSING, STATUS.COMPLETED].includes(slotProps.data.status)"
            text
            @click="analysisFile(slotProps.data.id)"
          ></Button>
          <span
            :class="[
              'status-label',
              {
                'status-failed': slotProps.data.status === STATUS.FAILED,
                'status-parsing': slotProps.data.status === STATUS.PARSING,
                'status-completed': slotProps.data.status === STATUS.COMPLETED,
                'status-default': slotProps.data.status === STATUS.ORIGIN
              }
            ]"
          >
            {{
              slotProps.data.status === STATUS.FAILED
                ? $t('kb.failedanalyse')
                : slotProps.data.status === STATUS.PARSING
                  ? $t('kb.parsing')
                  : slotProps.data.status === STATUS.COMPLETED
                    ? $t('kb.completed')
                    : $t('kb.originanalyse')
            }}
          </span>
          <Button
            :label="$t('kb.viewFile')"
            text
            :disabled="!viewFileList.includes(getFileType(slotProps.data.name))"
            @click="openFile(slotProps.data)"
          ></Button>
          <Button :label="$t('kb.delete')" text severity="danger" @click="removeFile($event, slotProps.data)"></Button>
        </template>
      </Column>
    </DataTable>
  </div>
  <Dialog
    v-model:visible="visible"
    modal
    :maximizable="fileViewerFlag"
    :header="dialogTitle"
    class="w-[50%] min-w-96"
    :content-style="fileType === 'pdf' ? 'height:100vh;' : 'min-height:200px'"
    @hide="resetDialog"
  >
    <FileViewer ref="fileViewerRef" v-if="fileViewerFlag" :fileId="fileId" :fileType="fileType" />
    <UploadFile ref="uploadFileRef" v-if="uploadFileFlag" :id="kbId" :showButton="true" @hide="close" @success="uploaded" />
  </Dialog>
</template>
<style scoped lang="scss">
.file-title {
  overflow: hidden;
  white-space: nowrap;
  word-break: break-all;
  text-overflow: ellipsis;
  max-width: 250px;
}
.button-group {
  display: flex;
  align-items: center;
  gap: 12px;
}
.status-label {
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  transition: all 0.3s ease;
  vertical-align: middle;
  line-height: 2; /* 与按钮行高匹配 */
  display: inline-flex;
  align-items: center;
}

.status-failed {
  color: #ff4d4f;
  background: #fff1f0;
  border: 1px solid #ffccc7;
}

.status-parsing {
  color: #1890ff;
  background: #e6f7ff;
  border: 1px solid #91d5ff;
}

.status-completed {
  color: #52c41a;
  background: #f6ffed;
  border: 1px solid #b7eb8f;
}

.status-default {
  color: #8c8c8c;
  background: #fafafa;
  border: 1px solid #d9d9d9;
}
</style>
